custom_css:
/* Crystal Clear Theme - 透明舒适版 */

/* 背景透明度调整 */
body {
    background: transparent !important;
}

/* 聊天区域透明背景 */
#chat { background: transparent !important; }

/* 消息气泡样式 - 圆角柔和 */
.mes {
    background: rgba(30, 30, 40, 0.4) !important;
    border-radius: 16px !important;
    backdrop-filter: blur(8px);
    margin: 8px 0 !important;
    border: 1px solid rgba(255, 255, 255, 0.1);
}

/* 用户消息气泡 */
.mes.user {
    background: rgba(40, 70, 100, 0.35) !important;
    border: 1px solid rgba(100, 150, 255, 0.2);
}

/* AI消息气泡 */
.mes[isbot="true"] {
    background: rgba(70, 40, 80, 0.3) !important;
    border: 1px solid rgba(180, 130, 255, 0.2);
}

/* 头像样式 - 圆形发光效果 */
.avatar {
    border-radius: 50% !important;
    border: 3px solid rgba(255, 255, 255, 0.3) !important;
    box-shadow: 0 0 15px rgba(150, 180, 255, 0.4), 0 4px 8px rgba(0, 0, 0, 0.3) !important;
    transition: all 0.3s ease !important;
}

.avatar:hover {
    border-color: rgba(255, 255, 255, 0.6) !important;
    box-shadow: 0 0 20px rgba(150, 180, 255, 0.6), 0 6px 12px rgba(0, 0, 0, 0.4) !important;
    transform: scale(1.05) !important;
}

/* 头像大小调整 */
.avatar-img {
    width: 80px !important;
    height: 80px !important;
    object-fit: cover !important;
}

/* 对话中的头像 */
.mes .avatar {
    width: 70px !important;
    height: 70px !important;
}

/* 文字阴影增强可读性 */
.mes_text {
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5) !important;
}

/* 滚动条美化 */
::-webkit-scrollbar {
    width: 10px !important;
}

::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2) !important;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb {
    background: rgba(150, 150, 180, 0.5) !important;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(180, 180, 220, 0.7) !important;
}

/* 输入框透明 */
#form_prompt {
    background: rgba(25, 25, 35, 0.6) !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(10px);
}

/* 发送按钮 */
#dialogue_send {
    background: linear-gradient(135deg, rgba(100, 150, 255, 0.6), rgba(150, 100, 255, 0.6)) !important;
    border: none !important;
    border-radius: 10px !important;
    transition: all 0.3s ease !important;
}

#dialogue_send:hover {
    background: linear-gradient(135deg, rgba(120, 170, 255, 0.8), rgba(170, 120, 255, 0.8)) !important;
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(100, 150, 255, 0.5);
}

/* 侧边栏半透明 */
#right-nav-panel,
#left-nav-panel {
    background: rgba(20, 20, 30, 0.7) !important;
    backdrop-filter: blur(15px);
}

/* 顶部导航栏 */
#top-bar-holder {
    background: rgba(20, 20, 30, 0.8) !important;
    backdrop-filter: blur(15px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
